// digits/symbols tables loaded from tables.json for this experiment
import fs from 'node:fs';
const T = JSON.parse(fs.readFileSync('/tmp/tables.json','utf8'));
const SYM = T.sym, DIG = T.dig, CODES = new Set(T.codes);

function digitsOf(code){ return Object.prototype.hasOwnProperty.call(DIG,code) ? DIG[code] : 2; }
function symbolOf(code){ return Object.prototype.hasOwnProperty.call(SYM,code) ? SYM[code] : code; }

// double -> {int:"...", frac:"..."} exact shortest-repr expansion
function expand(x){ // x >= 0 finite
  let s = String(x);
  let exp = 0;
  const e = s.indexOf('e');
  if (e >= 0){ exp = parseInt(s.slice(e+1),10); s = s.slice(0,e); }
  let dot = s.indexOf('.');
  let digits;
  if (dot >= 0){ digits = s.slice(0,dot)+s.slice(dot+1); exp -= (s.length - dot - 1); }
  else digits = s;
  // value = digits * 10^exp
  let int, frac;
  if (exp >= 0){ int = digits + '0'.repeat(exp); frac=''; }
  else {
    const k = -exp;
    if (k >= digits.length){ int='0'; frac='0'.repeat(k-digits.length)+digits; }
    else { int = digits.slice(0,digits.length-k); frac = digits.slice(digits.length-k); }
  }
  int = int.replace(/^0+(?=\d)/,'');
  return {int, frac};
}
function incr(ds){ // increment decimal digit string
  const a = ds.split('');
  let i = a.length-1;
  for(;i>=0;i--){ if(a[i]==='9'){a[i]='0';} else {a[i]=String.fromCharCode(a[i].charCodeAt(0)+1); break;} }
  if(i<0) a.unshift('1');
  return a.join('');
}
function quantHalfEven(int, frac, d){
  let keep = frac.slice(0,d); while(keep.length<d) keep+='0';
  const tail = frac.slice(d);
  let coef = int + keep;   // may have leading zeros
  let up = false;
  if (tail.length){
    const f = tail[0];
    if (f > '5') up = true;
    else if (f === '5'){
      if (/[1-9]/.test(tail.slice(1))) up = true;
      else up = ((coef.charCodeAt(coef.length-1) - 48) % 2) === 1;
    }
  }
  if (up) coef = incr(coef);
  coef = coef.replace(/^0+(?=\d)/,'');
  return coef;
}
function group(s){ return s.replace(/\B(?=(\d{3})+(?!\d))/g, ','); }

export function format(x, code){
  const sym = symbolOf(code), d = digitsOf(code);
  const neg = x < 0 || Object.is(x,-0);
  if (!isFinite(x)) return (neg?'-':'') + sym + '∞';
  const {int,frac} = expand(Math.abs(x));
  const coef = quantHalfEven(int,frac,d);
  if (coef.length > 28) throw new Error('InvalidOperation');
  let ip = d ? (coef.length>d ? coef.slice(0,coef.length-d) : '0') : coef;
  let fp = d ? coef.slice(-d).padStart(d,'0') : '';
  if (coef.length <= d) { ip='0'; fp = coef.padStart(d,'0'); }
  return (neg?'-':'') + sym + group(ip) + (d? '.'+fp : '');
}
