const d=require('/tmp/x19/pr.json');
const NP=/[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Cn}\p{Zl}\p{Zp}\p{Zs}]/u;
let bad=0, ex=[];
for(const [cp,p] of d){
  const ch=String.fromCodePoint(cp);
  const jsPrintable = cp===0x20 ? true : !NP.test(ch);
  if(jsPrintable!==p){bad++; if(ex.length<15)ex.push([cp.toString(16),p,jsPrintable]);}
}
console.log('bad',bad,JSON.stringify(ex));
